exercises.solution:
const mode = input("Mode ?");
const fiche = { quantite: "3" };
if (mode === "zero") { fiche.quantite = 0; }
if (mode === "positif") { fiche.quantite = 3; }
const valide = typeof fiche.quantite === "number" && Number.isFinite(fiche.quantite) && fiche.quantite >= 0;
console.log(valide);

